#!/bin/zsh
# Rebuilds everything extracted or generated from the local ULTRAKILL install and the mod's Minecraft dependency.
#
#   reference/decomp/     ULTRAKILL's game code (Assembly-CSharp), decompiled with ILSpy
#   reference/player/     the player prefab and physics settings, as JSON
#   reference/minecraft/  Minecraft 26.3 sources, as generated by Loom
#   mod/src/generated/    ULTRAKILL's sounds, first-person models with their animations, and icons, packaged into the mod
#
# Needs: dotnet + ilspycmd (dotnet tool install -g ilspycmd), uv, JDK 25.
set -euo pipefail

REPO=${0:A:h:h}
GAME=${ULTRAKILL_DIR:-"$HOME/Library/Application Support/CrossOver/Bottles/Steam/drive_c/Program Files (x86)/Steam/steamapps/common/ULTRAKILL"}
export DOTNET_ROOT=${DOTNET_ROOT:-/opt/homebrew/opt/dotnet/libexec}
export JAVA_HOME=${JAVA_HOME:-/opt/homebrew/opt/openjdk@25/libexec/openjdk.jdk/Contents/Home}

mkdir -p "$REPO/reference"

echo "Decompiling Assembly-CSharp..."
~/.dotnet/tools/ilspycmd -p -o "$REPO/reference/decomp" "$GAME/ULTRAKILL_Data/Managed/Assembly-CSharp.dll"

echo "Dumping the player prefab..."
uv run --quiet "$REPO/tools/dump_player.py"

echo "Extracting sounds..."
uv run --quiet "$REPO/tools/extract_sounds.py"

echo "Extracting models..."
uv run --quiet "$REPO/tools/extract_models.py"

echo "Generating Minecraft sources..."
(cd "$REPO/mod" && ./gradlew genSources --console=plain -q)
mkdir -p "$REPO/reference/minecraft"
for jar in "$REPO"/mod/.gradle/loom-cache/minecraftMaven/net/minecraft/minecraft-*/*/*-sources.jar; do
	unzip -qo "$jar" -d "$REPO/reference/minecraft"
done

echo "Done."
